const b = $input.first().json.body || $input.first().json;
const clean = v => (v === undefined || v === null) ? '' : String(v).trim();

const email = clean(b.email).toLowerCase();

let first = clean(b.firstName), last = clean(b.lastName);
if (!first) {
  const parts = clean(b.name).split(/\s+/).filter(Boolean);
  first = parts.shift() || '';
  last = parts.join(' ');
}

const rawPhone = clean(b.phone);
const d = rawPhone.replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
const phone = d.length === 10 ? '(' + d.slice(0,3) + ')' + d.slice(3,6) + '-' + d.slice(6) : rawPhone;

const formName = clean(b.source);
const searched = clean(b.searchedAddress);
let leadType = 'General';
if (/valuation|sell/i.test(formName) || searched) leadType = 'Seller';
if (/buyer|buy/i.test(formName) || /buyer/i.test(clean(b.formName))) leadType = 'Buyer';

const utmSource = clean(b.utm_source);
const metaLeadId = clean(b.leadgenId || b.leadId);
let origin;
if (metaLeadId) origin = 'Meta Instant Form';
else if (utmSource) origin = 'Paid ad: ' + utmSource;
else if (clean(b.referrer)) origin = 'Referral: ' + clean(b.referrer);
else origin = 'Website (organic/direct)';

return [{ json: {
  timestamp: DateTime.now().setZone('America/Chicago').toFormat('yyyy-LL-dd HH:mm'),
  first, last, email, phone, leadType, origin,
  campaign: clean(b.utm_campaign),
  ad: clean(b.utm_content),
  searchedAddress: searched,
  message: clean(b.message),
  metaLeadId,
  formName
} }];

const lead = $('Normalize Lead').first().json;
const rows = $input.all().map(i => i.json);

const norm = s => String(s || '').trim().toLowerCase();
const digits = s => String(s || '').replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
const leadPhone = digits(lead.phone);

let match = null;
for (const r of rows) {
  if (lead.email && norm(r['Email']) === norm(lead.email)) { match = r; break; }
  if (!match && leadPhone.length === 10 && digits(r['Phone']) === leadPhone) { match = r; }
}

const notes = match
  ? ('Already in Database as ' + [match['First Name'], match['Last Name']].filter(Boolean).join(' ')
     + ' (' + (match['Category'] || 'uncategorized') + ')').trim()
  : '';

return [{ json: { ...lead, alreadyInDatabase: match ? 'Y' : '', notes } }];

